import re

PATTERNS = {
    "email": re.compile(r"[\w.+-]+@[\w-]+\.[\w.-]+"),
    "account_id": re.compile(r"\bACC-\d{6,}\b"),
    "api_key": re.compile(r"\bsk-[A-Za-z0-9]{20,}\b"),
}

def sanitize(text):
    for label, pattern in PATTERNS.items():
        text = pattern.sub(f"[REDACTED_{label.upper()}]", text)
    return text

clean = sanitize(incident_report_text)

function sanitizeRecord(record, sensitiveFields) {
  const clean = { ...record };
  for (const field of sensitiveFields) {
    if (field in clean) clean[field] = "[REDACTED]";
  }
  return clean;
}

const safeCustomer = sanitizeRecord(customer, ["ssn", "cardNumber", "homeAddress"]);

def get_session_context(session_id, requesting_user_id):
    session = context_store.get(session_id)
    if session is None or session.owner_user_id != requesting_user_id:
        raise PermissionError("not authorized for this session")
    return session.context

